BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT116-S2-Q11$batch12$ AND q.stimulus=$batch12$After examining the options, the budget committee discovered that QI’s office-phone system would be inexpensive enough to be within the cost limit that had been set for the committee. However, Corelink’s system must also be inexpensive enough to be within the limit, since it is even less expensive than QI’s system.$batch12$ AND q.prompt=$batch12$The reasoning in the argument above is most closely paralleled by that in which one of the following?$batch12$ AND q.correct_choice=$batch12$E$batch12$) THEN RAISE EXCEPTION 'Question changed: PT116-S2-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT116-S2-Q11$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S2-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT116-S2-Q11$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Corelink's system is within the cost limit.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$QI's system is within the limit, and Corelink's is even cheaper.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Price alone sets whether a system is under the limit. QI is under, Corelink is lower still, so Corelink is under too.$batch12$), (3, $batch12$Goal$batch12$, $batch12$A meets a threshold on one measure. B is even further on that same measure. So B meets it too.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT116-S2-Q11$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Touching the ceiling depends on jumping too, not just height. Jeff might not jump as well.$batch12$), ($batch12$B$batch12$, $batch12$Running five miles depends on more than cigarettes smoked.$batch12$), ($batch12$C$batch12$, $batch12$Paul's level is lower, which moves away from the limit. That's the wrong direction.$batch12$), ($batch12$D$batch12$, $batch12$This concludes the darker chocolate "might" be right, a hedged and different claim.$batch12$), ($batch12$E$batch12$, $batch12$Sharp cheddar meets the low-fat standard, and mild cheddar has even less fat, so it meets the standard too. Same move.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT116-S2-Q11$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
